/* @prim:begin 38-wordmark */
.wordmark { font-family: var(--ds-font-mono); text-transform: uppercase; display: inline-flex; gap: 0.45em; align-items: baseline; max-width: none; }
.wordmark .wa { color: var(--cyan); font-weight: 800; letter-spacing: 0.22em; }
.wordmark .wf { color: var(--text-secondary); font-weight: 400; letter-spacing: 0.14em; }
/* @prim:end 38-wordmark */
[data-stage] .wordmark { font-size: var(--fs-headline); }

demo:
function wm(){var p=document.createElement('p');p.className='wordmark';p.setAttribute('aria-label','ARCS Field OS');p.innerHTML='<span class="wa">ARCS</span><span class="wf">Field OS</span>';return p;}
document.querySelector('[data-stage]').appendChild(wm());
document.querySelectorAll('[data-state]').forEach(function(el,i){var w=wm();w.style.fontSize=STATES[i][0];el.appendChild(w);});
